<?php
declare(strict_types=1);require __DIR__.'/app/request-supply.php';request_expire();$pageTitle='Equipment Requests';$marketActive='marketplace';$q=trim((string)($_GET['q']??''));$intent=(string)($_GET['intent']??'');$type=(string)($_GET['type']??'');$location=trim((string)($_GET['location']??''));$sql="SELECT r.*,o.name requester_name,o.marketplace_verified,t.name equipment_type,loc.canonical_name location_name,loc.country_name,COALESCE(NULLIF(rsc.artwork_url,''),NULLIF(tsc.artwork_url,''),'assets/images/equipment-placeholder.svg') request_image FROM marketplace_requests r JOIN owners o ON o.id=r.organization_id JOIN equipment_types t ON t.id=r.equipment_type_id LEFT JOIN equipment_subcategories rsc ON rsc.id=r.subcategory_id LEFT JOIN equipment_subcategories tsc ON tsc.id=t.subcategory_id JOIN marketplace_locations loc ON loc.id=r.required_location_id WHERE r.status IN ('OPEN','RESPONSES_RECEIVED') AND r.visibility='PUBLIC' AND r.response_deadline>UTC_TIMESTAMP()";$params=[];if($q!==''){$sql.=' AND (r.title LIKE ? OR r.description LIKE ? OR t.name LIKE ?)';$params=array_merge($params,array_fill(0,3,'%'.$q.'%'));}if(in_array($intent,['LEASE','PURCHASE','EITHER'],true)){$sql.=' AND r.intent=?';$params[]=$intent;}if($type!==''){$sql.=' AND r.equipment_type_id=?';$params[]=$type;}if($location!==''){$sql.=' AND (loc.canonical_name LIKE ? OR loc.country_name LIKE ?)';$params[]='%'.$location.'%';$params[]='%'.$location.'%';}$requests=rows($sql.' ORDER BY r.response_deadline,r.published_at DESC LIMIT 100',$params);$types=rows("SELECT DISTINCT t.id,t.name FROM marketplace_requests r JOIN equipment_types t ON t.id=r.equipment_type_id WHERE r.status IN ('OPEN','RESPONSES_RECEIVED') AND r.visibility='PUBLIC' AND r.response_deadline>UTC_TIMESTAMP() ORDER BY t.name");require __DIR__.'/includes/marketplace-header.php';?>
<section class="market-heading request-heading"><div><p class="market-kicker">LIVE DEMAND</p><h1>Equipment Requests</h1><p>Respond directly to verified industrial equipment requirements.</p></div><a class="market-button" href="requests?view=create">Request equipment</a></section><nav class="marketplace-mode-tabs"><a href="marketplace">Equipment Available</a><a href="marketplace-requests" aria-current="page">Equipment Required</a></nav><div class="request-market-shell"><aside class="market-filters"><form method="get"><h2>Find requests</h2><label>Search<input name="q" value="<?= e($q) ?>"></label><label>Intent<select name="intent"><option value="">Any</option><?php foreach(['LEASE','PURCHASE','EITHER'] as $option):?><option <?= $intent===$option?'selected':'' ?>><?= $option ?></option><?php endforeach;?></select></label><label>Equipment type<select name="type"><option value="">All types</option><?php foreach($types as $option):?><option value="<?= e($option['id']) ?>" <?= $type===$option['id']?'selected':'' ?>><?= e($option['name']) ?></option><?php endforeach;?></select></label><label>Location<input name="location" value="<?= e($location) ?>"></label><button class="market-button">Apply filters</button></form></aside><section class="market-results"><header><div><p class="market-kicker">EQUIPMENT REQUIRED</p><h2><?= count($requests) ?> active request<?= count($requests)===1?'':'s' ?></h2></div></header><?php if(!$requests):?><div class="market-empty"><h2>No active equipment requests match this view.</h2><p>Try clearing a filter or create a new request.</p></div><?php else:?><div class="market-grid"><?php foreach($requests as $request)require __DIR__.'/includes/request-card.php';?></div><?php endif;?></section></div>
<?php require __DIR__.'/includes/marketplace-footer.php';?>
